create or replace function public.get_checkout_payment_capabilities_v2() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('provider','iyzico','hostedCheckout',coalesce((cfg->>'checkout_form_enabled')::boolean,false),'savedCardPayment',coalesce((cfg->>'live_card_payments_enabled')::boolean,false),'cardEnrollment',coalesce((cfg->>'card_enrollment_enabled')::boolean,false)) from (select private.default_payment_control_v1() || coalesce(bs.public_config->'payments','{}'::jsonb) cfg from public.brand_settings bs where bs.slug='golden-oremar') s; $$;
create or replace function public.get_checkout_payment_capabilities_v1() returns jsonb language sql stable security invoker set search_path='' as $$ select public.get_checkout_payment_capabilities_v2(); $$;
create or replace function public.get_my_order_payment_state_v1(p_order_id uuid) returns jsonb language plpgsql security invoker set search_path='' as $$ declare caller_id uuid:=auth.uid(); target public.orders%rowtype; begin if caller_id is null then raise exception 'authentication_required' using errcode='42501'; end if; if p_order_id is null then raise exception 'order_id_required' using errcode='22023'; end if; select * into target from public.orders where id=p_order_id and user_id=caller_id; if target.id is null then raise exception 'order_not_found' using errcode='P0002'; end if; return jsonb_build_object('orderId',target.id,'orderNumber',target.order_number,'orderStatus',target.status,'paymentStatus',target.payment_status,'reservationExpiresAt',target.reservation_expires_at,'totalMinor',target.total_minor,'currency',target.currency); end; $$;
